class SplitExpressionFunctionReader(object):
    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")

    def __init__(self, *args, **kwargs):
        raise AttributeError("No constructor defined - class is abstract")
    __repr__ = _swig_repr

    def getSplitExpressionFunctionCount(self):
        r"""
        Get split expression function count.

        Split expression function is used for splitting an expression into multiple expressions.
        For example split expression function would split main expression cornerPuller into cornerPuller_L and cornerPuller_R,
        by splitting both joints and geometry vertices to the left and right side.
        Each resulting expression (cornerPuller_L and cornerPuller_R) points to its split expression function.

        Class dependencies:
        Expression -> SplitExpressionFunction --> SplitMap(s) -> Mesh
                                              |-> SplitJoint(s) -> JointGroup
        :rtype: int
        :return: Split expression function count.
        """
        return _py3rdf6_4_1.SplitExpressionFunctionReader_getSplitExpressionFunctionCount(self)

    def getSplitExpressionFunctionSourceExpressionIndex(self, functionIndex):
        r"""
        Get source expression for a given split function index.

        Source expression is the expression from which this expression is calculated.
        For example expression cornerPuller_L would have split expression function that points to source expression
        cornerPuller.
        :type functionIndex: int
        :param functionIndex: Split expression function index.
        :rtype: int
        :return: Source expression index.
        See also: ExpressionReader
        """
        return _py3rdf6_4_1.SplitExpressionFunctionReader_getSplitExpressionFunctionSourceExpressionIndex(self, functionIndex)

    def getSplitExpressionFunctionSplitMapIndices(self, functionIndex):
        r"""
        Get array of split map indices that belong to given split expression function.

        Split maps are applied to the source expression in order to mask out parts of the mesh deformation (per vertex) that
        are not needed. If split expression function has more than one split map, split maps are applied one after another
        making it a cumulative product. Formula: split_expression_vtx = source_expression_vtx * mask_1 * mask_2 * ... * mask_n
        :type functionIndex: int
        :param functionIndex: Split expression function index.
        :rtype: av::ConstArrayView< std::uint16_t >
        :return: Array of split map indices.
        See also: SplitMapReader
        """
        return _py3rdf6_4_1.SplitExpressionFunctionReader_getSplitExpressionFunctionSplitMapIndices(self, functionIndex)

    def getSplitExpressionFunctionSplitJointsIndices(self, functionIndex):
        r"""
        Get array of split joint indices that belong to given split expression function.

        Split joints are applied to the source expression in order to mask out parts of the joint animation that is not needed.
        If split expression function has more than one split joints, split joints are applied one after another making it a
        cumulative sum. Formula: split_expression_jnt = sum[source_expression_jnt * split_joints_multiplier_n *
        split_joints_group_n]
        :type functionIndex: int
        :param functionIndex: Split expression function index.
        :rtype: av::ConstArrayView< std::uint16_t >
        :return: Array of split joints indices.
        See also: SplitJointsReader
        """
        return _py3rdf6_4_1.SplitExpressionFunctionReader_getSplitExpressionFunctionSplitJointsIndices(self, functionIndex)

