    def __init__(self, *args, **kwargs):
        raise AttributeError("No constructor defined - class is abstract")
    __repr__ = _swig_repr

    def getPSDNetCount(self):
        r"""
        Get PSD net count.

        PSD net defines when and how corrective expressions are activated.
        Intensity of corrective expression's activation is equal to the product of activations of expressions that
        are part of the complex expression combination.
        For example, for expressions A, B and C, PSD definitions AB, AC, BC and ABC are defined.
        AB_cor expression activation is equal to the product of A and B expression activations. AB_cor = va*A * vb*B.
        Similarly, ABC_cor expression activation is equal to the product of A, B and C expressions. ABC_cor = va*A * vb*B *
        vc*C. Multipliers va, vb and vc are per expression weights that could be specified to make one expression more or less
        dominant. Those multipliers are almost always equal to 1.0. PSD net output activation value is always between 0.0
        and 1.0.
        :rtype: int
        :return: PSD net count.
        See also: PSDDefinitionReader
        """
        return _py3rdf6_4_1.PSDNetReader_getPSDNetCount(self)

